trees = nc.gobs.find(name="trees/", radius=200, limit=5)
for t in trees:
    print(t["name"], round(t["dist"]))

tree = nc.gobs.get(tree)
if tree is None:
    print("it fell")

barrel = nc.gobs.lifted()
if barrel is not None:
    print("carrying", barrel["name"])

held = nc.inv.hand()
if held:
    print("holding", held["name"])

it = nc.inv.item(it)
if it is None:
    print("gone")

sp = nc.inv.stockpile()
if sp and sp["free"] == 0:
    print("pile is full")

dest = nc.areas.for_item("Oak Block", direction="in")
if not dest:
    print("no area takes oak blocks")

